export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const command=(kind,args={})=>`data-command="${kind}" data-args="${esc(JSON.stringify(args))}"`;
const localTextFaces={'01022':'Evidence!','01023':'Dodge','01086':'Knife','02158':'Charisma','05313':'Hallowed Mirror','05314':'Soothing Melody',
 '05316':'Occult Lexicon','05317':'Blood-Rite','53002':'Survival Knife','01050':'Elusive'};
export function hasLocalTextFace(code){return Object.hasOwn(localTextFaces,code);}
export const img=(code,alt='',cls='')=>hasLocalTextFace(code)
 ?`<span class="card-text-face ${esc(cls)}">${esc(alt||localTextFaces[code])}</span>`
 :`<img class="${cls}" src="assets/${esc(code)}.png" alt="${esc(alt)}" loading="lazy">`;
export const inspect=(code,label='')=>`data-inspect="${esc(code)}" aria-label="Xem ${esc(label||code)}"`;
export const art=name=>`scene-art/${name}.png`;

export function handPlayOption(engine,index) {
 const s=engine.s,code=s.hand[index],card=engine.card(code);
 if(!['asset','event'].includes(card.type_code))return null;
 const cost=engine.playCost(code),fast=engine.isFastCard(code),reload=code==='01026';
 return {label:card.name,cost,fast,args:{kind:reload?'supply':'play',index},
  disabled:Boolean(['01010','01022','01023'].includes(code)||engine.isScreamedAlly(code)||s.voices||s.resources<cost||(reload&&!engine.firearms().length)||
   (code==='05314'&&!engine.canPlayMelody())||(code==='01050'&&!engine.canPlayElusive())||(!s.actions&&!fast))};
}

function actorMeter(symbol,label,current,max,style){
 const remaining=Math.max(0,max-current);
 return `<span class="actor-meter ${style}" aria-label="${label}: ${remaining}/${max}"><span aria-hidden="true">${symbol}</span><span class="actor-meter-track"><i style="width:${max>0?100*remaining/max:0}%"></i></span><b>${remaining}/${max}</b></span>`;
}
export function actorHud(engine,code,state){
 const c=engine.card(code);
 const meter=(type,current,max)=>actorMeter(type==='hp'?'♥':'◈',type==='hp'?'Sức khỏe':'Tinh thần',current,max,type);
 let stats;
 if(c.type_code==='enemy'){
  const values=[['⚔','Độ khó đánh',engine.enemyDifficulty(state,'fight')],['➶','Độ khó né',engine.enemyDifficulty(state,'evade')],['♥','Damage gây ra',c.enemy_damage??0],['◈','Horror gây ra',c.enemy_horror??0]];
  if(state.doom)values.push(['◆','Doom',state.doom]);
  stats=meter('hp',state.damage,engine.enemyHealth(state))+`<span class="actor-stats">${values.map(([icon,label,n])=>`<span title="${label}: ${n}" aria-label="${label}: ${n}">${icon}${n}</span>`).join('')}</span>`;
 }else if(c.type_code==='investigator'){
  stats=meter('hp',engine.s.hp,engine.healthLimit())+meter('horror',engine.s.horror,engine.sanityLimit());
 }else{
  stats=(c.health?meter('hp',state?.hp??0,c.health):'')+(c.sanity?meter('horror',state?.horror??0,c.sanity):'');
 }
 return stats?`<span class="actor-hud">${stats}</span>`:'';
}

